    import { Drawer } from "@vrembem/drawer";
    import { Popover } from "@vrembem/popover";

    customElements.define("vb-drawer", Drawer);
    customElements.define("vb-popover", Popover);
    ```
  </TabsPanel>
</CodeExample>

